package main

import (
	"context"
	"errors"
	"fmt"
	"time"

	"example.com/roombook/internal/retry"
)

type statusError struct{ code int }

func (e statusError) Error() string { return fmt.Sprintf("email provider answered %d", e.code) }

func retryable(err error) bool {
	var se statusError
	if errors.As(err, &se) {
		return se.code == 429 || se.code >= 502 && se.code <= 504
	}
	return errors.Is(err, context.DeadlineExceeded)
}

func main() {
	calls := 0
	send := func(ctx context.Context) error {
		calls++
		if calls < 4 {
			return statusError{503}
		}
		return nil
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	err := retry.Do(ctx, retry.Policy{
		Attempts:  5,
		Base:      200 * time.Millisecond,
		Max:       5 * time.Second,
		Retryable: retryable,
		OnRetry: func(err error, attempt int, wait time.Duration) {
			fmt.Printf("attempt %d failed (%v), waiting %v\n", attempt, err, wait.Round(time.Millisecond))
		},
	}, send)
	fmt.Printf("attempt %d done, err = %v\n", calls, err)
}

package main

import (
	"errors"
	"fmt"
	"time"

	"github.com/sony/gobreaker/v2"
)

func main() {
	redisUp := false
	cacheGet := func() (string, error) {
		fmt.Println("  asking Redis")
		if !redisUp {
			return "", errors.New("dial tcp 127.0.0.1:6379: connect: connection refused")
		}
		return "cached availability", nil
	}

	cb := gobreaker.NewCircuitBreaker[string](gobreaker.Settings{
		Name:    "redis",
		Timeout: time.Second, // how long it stays open
		ReadyToTrip: func(c gobreaker.Counts) bool {
			return c.ConsecutiveFailures >= 5
		},
		OnStateChange: func(name string, from, to gobreaker.State) {
			fmt.Printf("-> %s breaker: %s to %s\n", name, from, to)
		},
	})

	for i := 1; i <= 7; i++ {
		v, err := cb.Execute(cacheGet)
		if err != nil {
			v = "miss, ask PostgreSQL (" + err.Error() + ")"
		}
		fmt.Printf("request %d: %s\n", i, v)
	}
	redisUp = true
	time.Sleep(1100 * time.Millisecond)
	v, _ := cb.Execute(cacheGet)
	fmt.Printf("request 8: %s\n", v)
}

