package service

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"net/http"

	"example.com/roombook/internal/domain"
	"example.com/roombook/internal/store/postgres"
)

type KeyTx interface {
	BookingTx
	Claim(ctx context.Context, userID int64, key, hash string) (bool, error)
	Find(ctx context.Context, userID int64, key string) (postgres.SavedResponse, error)
	Complete(ctx context.Context, userID int64, key string, status int, body []byte) error
}

type Reply struct {
	Status   int
	Body     []byte
	Replayed bool
}

var errKeyReused = &domain.ProblemError{Status: http.StatusUnprocessableEntity,
	Type: "idempotency-key-reused", Detail: "This Idempotency-Key was used with a different request."}

func (s *BookingService) CreateOnce(ctx context.Context, key string, nb domain.NewBooking) (Reply, error) {
	canonical, _ := json.Marshal(nb)
	sum := sha256.Sum256(canonical)
	hash := hex.EncodeToString(sum[:])

	var reply Reply
	err := s.inKeyTx(ctx, func(tx KeyTx) error {
		claimed, err := tx.Claim(ctx, nb.UserID, key, hash)
		if err != nil {
			return err
		}
		if !claimed {
			saved, err := tx.Find(ctx, nb.UserID, key)
			if err != nil {
				return err
			}
			if saved.RequestHash != hash {
				return errKeyReused
			}
			reply = Reply{Status: saved.StatusCode, Body: saved.Body, Replayed: true}
			return nil
		}
		created, err := tx.Insert(ctx, nb)
		if err != nil {
			return err
		}
		body, _ := json.Marshal(created)
		reply = Reply{Status: http.StatusCreated, Body: body}
		return tx.Complete(ctx, nb.UserID, key, reply.Status, body)
	})
	return reply, err
}

func healthRoutes(mux *http.ServeMux, pool *pgxpool.Pool, ready *atomic.Bool) {
	// Liveness: the process is up and serving. Nothing else.
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "no-store")
		writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
	})
	// Readiness: send this instance traffic. False while draining, or without PostgreSQL.
	mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Cache-Control", "no-store")
		if !ready.Load() {
			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"status": "draining"})
			return
		}
		ctx, cancel := context.WithTimeout(r.Context(), time.Second)
		defer cancel()
		if err := pool.Ping(ctx); err != nil {
			writeJSON(w, http.StatusServiceUnavailable, map[string]any{"status": "unavailable", "failing": []string{"postgres"}})
			return
		}
		writeJSON(w, http.StatusOK, map[string]string{"status": "ready"})
	})
}

package main

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"net/http/httputil"
	"os"
	"sync/atomic"

	"github.com/jackc/pgx/v5/pgxpool"
)

// check calls both endpoints in memory and prints each raw response.
func check() {
	pool, err := pgxpool.New(context.Background(), os.Getenv("DATABASE_URL"))
	if err != nil {
		panic(err)
	}
	defer pool.Close()
	var ready atomic.Bool
	ready.Store(true)
	mux := http.NewServeMux()
	healthRoutes(mux, pool, &ready)
	srv := httptest.NewServer(mux)
	defer srv.Close()
	for _, path := range []string{"/healthz", "/readyz"} {
		res, err := http.Get(srv.URL + path)
		if err != nil {
			panic(err)
		}
		dump, _ := httputil.DumpResponse(res, true)
		fmt.Printf("%s\n", dump)
		res.Body.Close()
	}
}

func run(ctx context.Context, getenv func(string) string, stdout io.Writer) error {
	log := slog.New(slog.NewTextHandler(stdout, nil))
	ctx, stop := signal.NotifyContext(ctx, syscall.SIGTERM, os.Interrupt)
	defer stop()

	pool, err := pgxpool.New(ctx, getenv("DATABASE_URL"))
	if err != nil {
		return err
	}
	defer pool.Close()

	var ready atomic.Bool
	mux := http.NewServeMux()
	healthRoutes(mux, pool, &ready)
	srv := &http.Server{
		Addr:              "127.0.0.1:" + cmp.Or(getenv("PORT"), "8080"),
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
		IdleTimeout:       120 * time.Second,
	}

	go func() {
		if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
			log.Error("server failed", "err", err)
			stop()
		}
	}()
	ready.Store(true)
	log.Info("listening", "addr", srv.Addr)

	<-ctx.Done() // SIGTERM, or Ctrl+C
	log.Info("signal received: failing readiness, draining")
	ready.Store(false)
	time.Sleep(5 * time.Second) // let the load balancer notice

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
	defer cancel()
	log.Info("shutting down: no new connections, waiting for requests in flight")
	if err := srv.Shutdown(shutdownCtx); err != nil {
		return fmt.Errorf("shutdown: %w", err)
	}
	log.Info("server stopped, closing the pool")
	return nil
}

