package outbox

import (
	"context"
	"encoding/json"
	"fmt"
	"log/slog"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"github.com/redis/go-redis/v9"
)

// Relay moves committed events from the outbox table to the roombook:events stream.
func Relay(ctx context.Context, pool *pgxpool.Pool, rdb *redis.Client, log *slog.Logger) {
	for ctx.Err() == nil {
		moved, err := relayBatch(ctx, pool, rdb)
		if err != nil {
			log.ErrorContext(ctx, "outbox relay", "err", err)
		}
		if moved == 0 {
			select {
			case <-time.After(time.Second):
			case <-ctx.Done():
			}
		}
	}
}

func relayBatch(ctx context.Context, pool *pgxpool.Pool, rdb *redis.Client) (int, error) {
	var moved int
	err := pgx.BeginFunc(ctx, pool, func(tx pgx.Tx) error {
		rows, err := tx.Query(ctx, `
			SELECT id, event_type, payload FROM outbox
			WHERE published_at IS NULL
			ORDER BY id LIMIT 100
			FOR UPDATE SKIP LOCKED`)
		if err != nil {
			return err
		}
		var ids []int64
		for rows.Next() {
			var id int64
			var typ string
			var payload json.RawMessage
			if err := rows.Scan(&id, &typ, &payload); err != nil {
				return err
			}
			err := rdb.XAdd(ctx, &redis.XAddArgs{
				Stream: "roombook:events",
				Values: map[string]any{"eventId": fmt.Sprintf("evt_%d", id), "type": typ, "payload": string(payload)},
			}).Err()
			if err != nil {
				return err
			}
			ids = append(ids, id)
		}
		if err := rows.Err(); err != nil {
			return err
		}
		moved = len(ids)
		if moved == 0 {
			return nil
		}
		_, err = tx.Exec(ctx, `UPDATE outbox SET published_at = now() WHERE id = ANY($1)`, ids)
		return err
	})
	return moved, err
}

package webhook

import (
	"encoding/json"
	"io"
	"net/http"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

type emailEvent struct {
	ID   string `json:"id"`
	Type string `json:"type"`
	Data struct {
		To string `json:"to"`
	} `json:"data"`
}

func EmailEvents(pool *pgxpool.Pool, secret string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		raw, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 100<<10))
		if err != nil {
			http.Error(w, "body too large", http.StatusRequestEntityTooLarge)
			return
		}
		if !Verify(secret, r.Header.Get("Roombook-Signature"), raw, time.Now()) {
			http.Error(w, "signature check failed", http.StatusUnauthorized)
			return
		}
		var ev emailEvent
		if err := json.Unmarshal(raw, &ev); err != nil {
			http.Error(w, "bad JSON", http.StatusBadRequest)
			return
		}
		err = pgx.BeginFunc(r.Context(), pool, func(tx pgx.Tx) error {
			tag, err := tx.Exec(r.Context(),
				`INSERT INTO processed_events (event_id) VALUES ($1) ON CONFLICT DO NOTHING`, ev.ID)
			if err != nil || tag.RowsAffected() == 0 || ev.Type != "email.bounced" {
				return err
			}
			_, err = tx.Exec(r.Context(),
				`UPDATE users SET email_bounced_at = now() WHERE lower(email) = lower($1)`, ev.Data.To)
			return err
		})
		if err != nil {
			http.Error(w, "try again", http.StatusInternalServerError)
			return
		}
		w.WriteHeader(http.StatusNoContent)
	}
}
